"""Compile the phone's single token source for WebView, Android and Flutter."""
from pathlib import Path
import json,re,base64

ROOT=Path(__file__).resolve().parent
def sync():
    spec=json.loads((ROOT/'design-system.json').read_text(encoding='utf-8'))
    colors,metrics=spec['colors'],spec['metrics']
    light=spec.get('lightColors',colors)
    def argb(value):
        raw=value.lstrip('#')
        return (raw[6:]+raw[:6] if len(raw)==8 else 'FF'+raw).upper()
    def kebab(value):return re.sub(r'([A-Z])',lambda m:'-'+m[1].lower(),value)
    outputs={}
    css='/* Generated by phone_design_system.py from design-system.json. */\n:root{\n'
    css+=''.join(f' --phone-{kebab(k)}:{v};\n' for k,v in colors.items())
    css+=''.join(f' --phone-{kebab(k)}:{v}px;\n' for k,v in metrics.items())+'}\n'
    css+=':root[data-app-appearance=light]{\n'+''.join(f' --phone-{kebab(k)}:{v};\n' for k,v in light.items())+'}\n'
    mark=base64.b64encode((ROOT/'assets/ui/morph-wordmark.webp').read_bytes()).decode('ascii')
    css+=':root{--phone-wordmark-mask:url("data:image/webp;base64,'+mark+'")}\n'
    outputs[ROOT/'assets/ui/phone-tokens.css']=css
    kt='// Generated from mobile-app/design-system.json.\npackage tv.appbridge.phase0.rt.ui\n\nobject PhoneDesignTokens {\n'
    kt+=''.join(f' val {k}=0x{argb(v)}.toInt()\n' for k,v in colors.items())
    kt+=''.join(f' val light{k[0].upper()+k[1:]}=0x{argb(v)}.toInt()\n' for k,v in light.items())
    kt+=''.join(f' const val {k}={v}\n' for k,v in metrics.items())+'}\n'
    outputs[ROOT/'bridge-native/src/main/java/tv/appbridge/phase0/rt/ui/PhoneDesignTokens.kt']=kt
    dart="// Generated from mobile-app/design-system.json.\nimport 'package:flutter/material.dart';\n\nabstract final class PhoneDesignTokens {\n"
    dart+=''.join(f' static const {k}=Color(0x{argb(v)});\n' for k,v in colors.items())
    dart+=f' static const bool decorativeArtwork={str(spec.get("decorativeArtwork",False)).lower()};\n'
    dart+=''.join(f' static const light{k[0].upper()+k[1:]}=Color(0x{argb(v)});\n' for k,v in light.items())
    dart+=''.join(f' static const double {k}={v}.0;\n' for k,v in metrics.items())
    dart+=' static const background=RadialGradient(center:Alignment.topRight,radius:1.2,colors:[backgroundTop,backgroundMiddle,backgroundBottom],stops:[0,.45,1]);\n'
    dart+=' static const glass=LinearGradient(begin:Alignment.topLeft,end:Alignment.bottomRight,colors:[glassTop,glassBottom]);\n'
    dart+=' static const action=LinearGradient(begin:Alignment.topLeft,end:Alignment.bottomRight,colors:[accent,accentEnd]);\n'
    dart+=' static TextStyle uiText({TextStyle? textStyle,double? fontSize,FontWeight? fontWeight,Color? color,Paint? foreground,double? height}) => (textStyle??const TextStyle()).copyWith(fontFamily:"MorphSans",fontSize:fontSize==null?bodySize:fontSize<=12?captionSize:fontSize<=16?bodySize:fontSize<=20?sectionSize:fontSize<=28?titleSize:fontSize,fontWeight:fontWeight,color:foreground==null?color:null,foreground:foreground,height:height??1.6);\n'
    dart+=' static BoxDecoration cardDecoration({bool elevated=true}) => BoxDecoration(gradient:glass,borderRadius:BorderRadius.circular(cardRadius),border:Border.all(color:border),boxShadow:elevated?cardShadow:null);\n'
    dart+=' static PhonePalette palette(bool dark) => darkPalette;\n'
    for mode,values in [('dark',colors),('light',light)]:
        dart+=f' static const {mode}Palette=PhonePalette('+','.join(f'{k}:Color(0x{argb(v)})' for k,v in values.items())+');\n'
    dart+=' static const cardShadow=[BoxShadow(color:shadow,blurRadius:16,offset:Offset(0,4))];\n}\n'
    dart+='class PhonePalette { const PhonePalette({'+','.join(f'required this.{k}' for k in colors)+'});\n'
    dart+=''.join(f' final Color {k};\n' for k in colors)
    dart+=' RadialGradient get background=>RadialGradient(center:Alignment.topRight,radius:1.2,colors:[backgroundTop,backgroundMiddle,backgroundBottom],stops:[0,.45,1]);\n'
    dart+=' LinearGradient get glass=>LinearGradient(begin:Alignment.topLeft,end:Alignment.bottomRight,colors:[glassTop,glassBottom]);\n'
    dart+=' LinearGradient get action=>LinearGradient(begin:Alignment.topLeft,end:Alignment.bottomRight,colors:[accent,accentEnd]);\n'
    dart+=' BoxDecoration cardDecoration({bool elevated=true})=>BoxDecoration(gradient:glass,borderRadius:BorderRadius.circular(PhoneDesignTokens.cardRadius),border:Border.all(color:border),boxShadow:elevated?[BoxShadow(color:shadow,blurRadius:16,offset:Offset(0,4))]:null);\n}\n'
    outputs[ROOT/'integrated-remote/lib/core/theme/phone_design_tokens.dart']=dart
    java='// Generated from mobile-app/design-system.json.\npackage local.cleartv.mobile;\npublic final class PhoneDesignTokens { private PhoneDesignTokens() {}\n'
    java+=''.join(f' public static final int {kebab(k).replace("-","_").upper()}=0x{argb(v)};\n' for k,v in colors.items())
    java+=''.join(f' public static final int LIGHT_{kebab(k).replace("-","_").upper()}=0x{argb(v)};\n' for k,v in light.items())
    java+=''.join(f' public static final int {kebab(k).replace("-","_").upper()}={v};\n' for k,v in metrics.items())+'}\n'
    outputs[ROOT/'src/local/cleartv/mobile/PhoneDesignTokens.java']=java
    android_res=ROOT/'integrated-remote/android/app/src/main/res'
    outputs[android_res/'values/phone_colors.xml']='<resources><color name="phone_canvas">'+colors['backgroundBase']+'</color></resources>\n'
    for qualifier in ['values','values-night']:
        outputs[android_res/qualifier/'styles.xml']='<resources>\n<style name="LaunchTheme" parent="@android:style/Theme.Black.NoTitleBar"><item name="android:windowBackground">@drawable/launch_background</item><item name="android:statusBarColor">@color/phone_canvas</item><item name="android:navigationBarColor">@color/phone_canvas</item><item name="android:windowLightStatusBar">false</item></style>\n<style name="NormalTheme" parent="@android:style/Theme.Black.NoTitleBar"><item name="android:windowBackground">@color/phone_canvas</item><item name="android:statusBarColor">@color/phone_canvas</item><item name="android:navigationBarColor">@color/phone_canvas</item><item name="android:windowLightStatusBar">false</item></style>\n</resources>\n'
    for qualifier in ['drawable','drawable-v21']:
        outputs[android_res/qualifier/'launch_background.xml']='<layer-list xmlns:android="http://schemas.android.com/apk/res/android"><item android:drawable="@color/phone_canvas"/></layer-list>\n'
    for path,content in outputs.items():
        path.parent.mkdir(parents=True,exist_ok=True)
        if not path.exists() or path.read_text(encoding='utf-8')!=content:path.write_text(content,encoding='utf-8')
    import shutil
    symbol=ROOT.parent/'tv-project/app/assets/morph-header-symbol.webp'
    for target in [ROOT/'assets/ui/morph-header-symbol.webp',ROOT/'integrated-remote/assets/morph-header-symbol.webp']:
        shutil.copy2(symbol,target)
    from phone_layout import compile_layout
    compile_layout()
    return outputs
if __name__=='__main__':sync()
